export type AccessListEntry = {
    address: string;
    storageKeys: Array<string>;
};

export interface ActionRejectedError extends quaisError<'ACTION_REJECTED'> {
    /**
     * The requested action.
     */
    action: 'requestAccess' | 'sendTransaction' | 'signMessage' | 'signTransaction' | 'signTypedData' | 'unknown';
    /**
     * The reason the action was rejected.
     *
     * If there is already a pending request, some clients may indicate there is already a `"pending"` action. This
     * prevents an app from spamming the user.
     */
    reason: 'expired' | 'rejected' | 'pending';
}

export interface Addressable {
    /**
     * Get the object address.
     */
    getAddress(): Promise<string>;
}

export declare enum AddressStatus {
    USED = "USED",
    UNUSED = "UNUSED",
    ATTEMPTED_USE = "ATTEMPTED_USE",
    UNKNOWN = "UNKNOWN"
}

export interface BadDataError extends quaisError<'BAD_DATA'> {
    /**
     * The data.
     */
    value: any;
}

export interface BaseContractMethod<A extends Array<any> = Array<any>, R = any, D extends R | ContractTransactionResponse = R | ContractTransactionResponse> {
    /**
     * Call the contract method with arguments.
     *
     * @param {...ContractMethodArgs<A>} args - The arguments to call the method with.
     * @returns {Promise<D>} A promise resolving to the result of the call.
     */
    (...args: ContractMethodArgs<A>): Promise<D>;
    /**
     * The name of the Contract method.
     */
    name: string;
    /**
     * The fragment of the Contract method. This will throw on ambiguous method names.
     */
    fragment: FunctionFragment;
    /**
     * Returns the fragment constrained by `args`. This can be used to resolve ambiguous method names.
     *
     * @param {ContractMethodArgs<A>} args - The arguments to constrain the fragment by.
     * @returns {FunctionFragment} The constrained fragment.
     */
    getFragment(...args: ContractMethodArgs<A>): FunctionFragment;
    /**
     * Returns a populated transaction that can be used to perform the contract method with `args`.
     *
     * @param {ContractMethodArgs<A>} args - The arguments to populate the transaction with.
     * @returns {Promise<ContractTransaction>} A promise resolving to the populated transaction.
     */
    populateTransaction(...args: ContractMethodArgs<A>): Promise<ContractTransaction>;
    /**
     * Call the contract method with `args` and return the value.
     *
     * If the return value is a single type, it will be dereferenced and returned directly, otherwise the full Result
     * will be returned.
     *
     * @param {ContractMethodArgs<A>} args - The arguments to call the method with.
     * @returns {Promise<R>} A promise resolving to the result of the static call.
     */
    staticCall(...args: ContractMethodArgs<A>): Promise<R>;
    /**
     * Send a transaction for the contract method with `args`.
     *
     * @param {ContractMethodArgs<A>} args - The arguments to call the method with.
     * @returns {Promise<ContractTransactionResponse>} A promise resolving to the transaction response.
     */
    send(...args: ContractMethodArgs<A>): Promise<ContractTransactionResponse>;
    /**
     * Estimate the gas to send the contract method with `args`.
     *
     * @param {ContractMethodArgs<A>} args - The arguments to call the method with.
     * @returns {Promise<bigint>} A promise resolving to the estimated gas.
     */
    estimateGas(...args: ContractMethodArgs<A>): Promise<bigint>;
    /**
     * Call the contract method with `args` and return the Result without any dereferencing.
     *
     * @param {ContractMethodArgs<A>} args - The arguments to call the method with.
     * @returns {Promise<Result>} A promise resolving to the Result of the static call.
     */
    staticCallResult(...args: ContractMethodArgs<A>): Promise<Result>;
}

export interface BlockParams {
    outboundEtxs: ReadonlyArray<string | ExternalTransactionResponseParams>;
    hash: string;
    header: BlockHeaderParams;
    interlinkHashes: Array<string>;
    size: bigint;
    subManifest: Array<string>;
    totalEntropy: bigint;
    transactions: ReadonlyArray<string | TransactionResponseParams | ExternalTransactionResponseParams>;
    uncles: Array<string | UncleParams>;
    woHeader: WoHeaderParams;
    workShares: Array<string | WorkShareParams>;
}

export interface BufferOverrunError extends quaisError<'BUFFER_OVERRUN'> {
    /**
     * The buffer that was overrun.
     */
    buffer: Uint8Array;
    /**
     * The length of the buffer.
     */
    length: number;
    /**
     * The offset that was requested.
     */
    offset: number;
}

export interface CallExceptionError extends quaisError<'CALL_EXCEPTION'> {
    /**
     * The action being performed when the revert was encountered.
     */
    action: CallExceptionAction;
    /**
     * The revert data returned.
     */
    data: null | string;
    /**
     * A human-readable representation of data, if possible.
     */
    reason: null | string;
    /**
     * The transaction that triggered the exception.
     */
    transaction: CallExceptionTransaction;
    /**
     * The contract invocation details, if available.
     */
    invocation: null | {
        method: string;
        signature: string;
        args: Array<any>;
    };
    /**
     * The built-in or custom revert error, if available
     */
    revert: null | {
        signature: string;
        name: string;
        args: Array<any>;
    };
    /**
     * If the error occurred in a transaction that was mined (with a status of `0`), this is the receipt.
     */
    receipt?: TransactionReceipt;
}

export type CallExceptionTransaction = {
    to: null | string;
    from?: string;
    data: string;
};

export interface ContractEvent<A extends Array<any> = Array<any>> {
    /**
     * Create a deferred topic filter for the event.
     *
     * @param {...ContractEventArgs<A>} args - The arguments to create the filter with.
     * @returns {DeferredTopicFilter} The deferred topic filter.
     */
    (...args: ContractEventArgs<A>): DeferredTopicFilter;
    /**
     * The name of the Contract event.
     */
    name: string;
    /**
     * The fragment of the Contract event. This will throw on ambiguous method names.
     */
    fragment: EventFragment;
    /**
     * Returns the fragment constrained by `args`. This can be used to resolve ambiguous event names.
     *
     * @param {ContractEventArgs<A>} args - The arguments to constrain the fragment by.
     * @returns {EventFragment} The constrained fragment.
     */
    getFragment(...args: ContractEventArgs<A>): EventFragment;
}

export type ContractEventArgs<A extends Array<any>> = {
    [I in keyof A]?: A[I] | Typed | null;
};

export interface ContractInterface {
    [name: string]: BaseContractMethod;
}

export type ContractMethodArgs<A extends Array<any>> = PostfixOverrides<{
    [I in keyof A]-?: A[I] | Typed;
}>;

export interface ContractRunner {
    /**
     * The provider used for necessary state querying operations.
     *
     * This can also point to the **ContractRunner** itself, in the case of an
     * [AbstractProvider](../classes/AbstractProvider).
     */
    provider: null | Provider;
    /**
     * Required to estimate gas.
     *
     * @param {TransactionRequest} tx - The transaction object.
     * @returns {Promise<bigint>} A promise resolving to the estimated gas.
     */
    estimateGas?: (tx: TransactionRequest) => Promise<bigint>;
    /**
     * Required for pure, view or static calls to contracts.
     *
     * @param {QuaiTransactionRequest} tx - The transaction object.
     * @returns {Promise<string>} A promise resolving to the result of the call.
     */
    call?: (tx: QuaiTransactionRequest) => Promise<string>;
    /**
     * Required for state mutating calls
     *
     * @param {TransactionRequest} tx - The transaction object.
     * @returns {Promise<TransactionResponse>} A promise resolving to the transaction response.
     */
    sendTransaction?: (tx: TransactionRequest) => Promise<TransactionResponse>;
    /**
     * Required for populating access lists for state mutating calls
     *
     * @param tx
     * @returns {Promise<AccessList>}
     */
    createAccessList?: (tx: QuaiTransactionRequest) => Promise<AccessList>;
}

export interface ContractTransaction extends QuaiPreparedTransactionRequest {
    /**
     * The target address.
     */
    to: string;
    /**
     * The transaction data.
     */
    data: string;
    /**
     * The from address, if any.
     */
    from: string;
}

export type DebugEventBrowserProvider = {
    action: 'sendEip1193Payload';
    payload: {
        method: string;
        params: Array<any>;
    };
} | {
    action: 'receiveEip1193Result';
    result: any;
} | {
    action: 'receiveEip1193Error';
    error: Error;
};

export interface DeferredTopicFilter {
    /**
     * Get the topic filter.
     *
     * @returns {Promise<TopicFilter>} A promise resolving to the topic filter.
     */
    getTopicFilter(): Promise<TopicFilter>;
    /**
     * The fragment of the event.
     */
    fragment: EventFragment;
}

export interface Eip1193Provider {
    /**
     * See [EIP-1193](https://eips.ethereum.org/EIPS/eip-1193) for details on this method.
     *
     * @param {Object} request - The request object.
     * @param {string} request.method - The method name.
     * @param {any[] | Record<string, any>} [request.params] - The parameters for the method.
     * @param {Shard} [request.shard] - The shard to send the request to.
     * @returns {Promise<any>} The result of the request.
     */
    request(request: {
        method: string;
        params?: Array<any> | Record<string, any>;
        shard?: Shard;
    }): Promise<any>;
}

export type EncryptOptions = {
    progressCallback?: ProgressCallback;
    iv?: BytesLike;
    entropy?: BytesLike;
    client?: string;
    salt?: BytesLike;
    uuid?: string;
    scrypt?: {
        N?: number;
        r?: number;
        p?: number;
    };
};

export interface EventEmitterable<T> {
    /**
     * Registers a `listener` that is called whenever the `event` occurs until unregistered.
     */
    on(event: T, listener: Listener, zone?: Zone): Promise<this>;
    /**
     * Registers a `listener` that is called the next time `event` occurs.
     */
    once(event: T, listener: Listener, zone?: Zone): Promise<this>;
    /**
     * Triggers each listener for `event` with the `args`.
     */
    emit(event: T, zone?: Zone, ...args: Array<any>): Promise<boolean>;
    /**
     * Resolves to the number of listeners for `event`.
     */
    listenerCount(event?: T): Promise<number>;
    /**
     * Resolves to the listeners for `event`.
     */
    listeners(event?: T): Promise<Array<Listener>>;
    /**
     * Unregister the `listener` for `event`. If `listener` is unspecified, all listeners are unregistered.
     */
    off(event: T, listener?: Listener, zone?: Zone): Promise<this>;
    /**
     * Unregister all listeners for `event`.
     */
    removeAllListeners(event?: T): Promise<this>;
    /**
     * Alias for {@link EventEmitterable.on | **on**}.
     */
    addListener(event: T, listener: Listener, zone?: Zone): Promise<this>;
    /**
     * Alias for {@link EventEmitterable.off | **off**}.
     */
    removeListener(event: T, listener: Listener, zone?: Zone): Promise<this>;
}

export interface EventFilter {
    address?: AddressLike | Array<AddressLike>;
    topics?: TopicFilter;
    nodeLocation?: NodeLocation;
}

export interface Filter extends EventFilter {
    /**
     * The start block for the filter (inclusive).
     */
    fromBlock?: BlockTag;
    /**
     * The end block for the filter (inclusive).
     */
    toBlock?: BlockTag;
}

export interface FilterByBlockHash extends EventFilter {
    /**
     * The blockhash of the specific block for the filter.
     */
    blockHash?: string;
    zone: Zone;
}

export type FixedFormat = number | string | {
    signed?: boolean;
    width?: number;
    decimals?: number;
};

export type GetUrlResponse = {
    statusCode: number;
    statusMessage: string;
    headers: Record<string, string>;
    body: null | Uint8Array;
};

export interface InsufficientFundsError extends quaisError<'INSUFFICIENT_FUNDS'> {
    /**
     * The transaction.
     */
    transaction: TransactionRequest;
}

export interface InvalidArgumentError extends quaisError<'INVALID_ARGUMENT'> {
    /**
     * The name of the argument.
     */
    argument: string;
    /**
     * The value that was provided.
     */
    value: any;
    info?: Record<string, any>;
}

export interface JsonFragment {
    /**
     * The name of the error, event, function, etc.
     */
    readonly name?: string;
    /**
     * The type of the fragment (e.g. `event`, `"function"`, etc.)
     */
    readonly type?: string;
    /**
     * If the event is anonymous.
     */
    readonly anonymous?: boolean;
    /**
     * If the function is payable.
     */
    readonly payable?: boolean;
    /**
     * If the function is constant.
     */
    readonly constant?: boolean;
    /**
     * The mutability state of the function.
     */
    readonly stateMutability?: string;
    /**
     * The input parameters.
     */
    readonly inputs?: ReadonlyArray<JsonFragmentType>;
    /**
     * The output parameters.
     */
    readonly outputs?: ReadonlyArray<JsonFragmentType>;
    /**
     * The gas limit to use when sending a transaction for this function.
     */
    readonly gas?: string;
}

export interface JsonFragmentType {
    /**
     * The parameter name.
     */
    readonly name?: string;
    /**
     * If the parameter is indexed.
     */
    readonly indexed?: boolean;
    /**
     * The type of the parameter.
     */
    readonly type?: string;
    /**
     * The internal Solidity type.
     */
    readonly internalType?: string;
    /**
     * The components for a tuple.
     */
    readonly components?: ReadonlyArray<JsonFragmentType>;
}

export type JsonRpcApiProviderOptions = {
    staticNetwork?: null | Network | boolean;
    batchStallTime?: number;
    batchMaxSize?: number;
    batchMaxCount?: number;
    cacheTimeout?: number;
    usePathing?: boolean;
    shardPorts?: ShardPorts | ShardPorts[] | false;
    shardPaths?: ShardPaths | ShardPaths[] | false;
    shards?: Shard[] | Shard[][] | false;
};

export type JsonRpcError = {
    /**
     * The response ID to match it to the relevant request.
     */
    id: number;
    /**
     * The response error.
     */
    error: {
        code: number;
        message?: string;
        data?: any;
        shard?: Shard;
    };
};

export type JsonRpcPayload = {
    /**
     * The JSON-RPC request ID.
     */
    id: number;
    /**
     * The JSON-RPC request method.
     */
    method: string;
    /**
     * The JSON-RPC request parameters.
     */
    params: Array<any> | Record<string, any>;
    /**
     * A required constant in the JSON-RPC specification.
     */
    jsonrpc: '2.0';
};

export type JsonRpcResult = {
    /**
     * The response ID to match it to the relevant request.
     */
    id: number;
    /**
     * The response result.
     */
    result: any;
};

export type KeystoreAccount = {
    address: string;
    privateKey: string;
    mnemonic?: {
        path?: string;
        locale?: string;
        entropy: string;
    };
};

export declare enum Ledger {
    Quai = 0,
    Qi = 1
}

export interface LogParams {
    /**
     * The transaction hash for the transaxction the log occurred in.
     */
    transactionHash: string;
    /**
     * The block hash of the block that included the transaction for this log.
     */
    blockHash: string;
    /**
     * The block number of the block that included the transaction for this log.
     */
    blockNumber: number;
    /**
     * Whether this log was removed due to the transaction it was included in being removed dur to an orphaned block.
     */
    removed: boolean;
    /**
     * The address of the contract that emitted this log.
     */
    address: string;
    /**
     * The data emitted with this log.
     */
    data: string;
    /**
     * The topics emitted with this log.
     */
    topics: ReadonlyArray<string>;
    /**
     * The index of this log.
     */
    index: number;
    /**
     * The transaction index of this log.
     */
    transactionIndex: number;
}

export interface MissingArgumentError extends quaisError<'MISSING_ARGUMENT'> {
    /**
     * The number of arguments received.
     */
    count: number;
    /**
     * The number of arguments expected.
     */
    expectedCount: number;
}

export interface NetworkError extends quaisError<'NETWORK_ERROR'> {
    /**
     * The network event.
     */
    event: string;
}

export type Networkish = Network | number | bigint | string | {
    name?: string;
    chainId?: number;
};

export interface NeuteredAddressInfo {
    pubKey: string;
    address: string;
    account: number;
    index: number;
    zone: Zone;
}

export interface NonceExpiredError extends quaisError<'NONCE_EXPIRED'> {
    /**
     * The transaction.
     */
    transaction: TransactionRequest;
}

export interface NotImplementedError extends quaisError<'NOT_IMPLEMENTED'> {
    /**
     * The attempted operation.
     */
    operation: string;
}

export interface NumericFaultError extends quaisError<'NUMERIC_FAULT'> {
    /**
     * The attempted operation.
     */
    operation: string;
    /**
     * The fault reported.
     */
    fault: string;
    /**
     * The value the operation was attempted against.
     */
    value: any;
}

export type OrphanFilter = {
    orphan: 'drop-block';
    hash: string;
    number: number;
} | {
    orphan: 'drop-transaction';
    tx: {
        hash: string;
        blockHash: string;
        blockNumber: number;
    };
    other?: {
        hash: string;
        blockHash: string;
        blockNumber: number;
    };
} | {
    orphan: 'reorder-transaction';
    tx: {
        hash: string;
        blockHash: string;
        blockNumber: number;
    };
    other?: {
        hash: string;
        blockHash: string;
        blockNumber: number;
    };
} | {
    orphan: 'drop-log';
    log: {
        transactionHash: string;
        blockHash: string;
        blockNumber: number;
        address: string;
        data: string;
        topics: ReadonlyArray<string>;
        index: number;
    };
};

export interface OutpointInfo {
    outpoint: Outpoint;
    address: string;
    zone: Zone;
    derivationPath: DerivationPath;
    account?: number;
}

export type PerformActionFilter = {
    address?: string | Array<string>;
    topics?: Array<null | string | Array<string>>;
    fromBlock?: BlockTag;
    toBlock?: BlockTag;
    nodeLocation: NodeLocation;
} | {
    address?: string | Array<string>;
    topics?: Array<null | string | Array<string>>;
    blockHash?: string;
    nodeLocation: NodeLocation;
};

export type PerformActionRequest = {
    method: 'broadcastTransaction';
    signedTransaction: string;
    zone: Zone;
} | {
    method: 'calculateConversionAmount';
    transactionArgs: ConversionTransactionRequest;
} | {
    method: 'call';
    transaction: PerformActionTransaction;
    blockTag: BlockTag;
    zone?: Zone;
} | {
    method: 'chainId';
    zone?: Zone;
} | {
    method: 'estimateGas';
    transaction: PerformActionTransaction;
    zone?: Zone;
} | {
    method: 'estimateFeeForQi';
    transaction: QiPerformActionTransaction;
    zone?: Zone;
} | {
    method: 'createAccessList';
    transaction: PerformActionTransaction;
    zone?: Zone;
} | {
    method: 'getBalance';
    address: string;
    blockTag: BlockTag;
    zone: Zone;
} | {
    method: 'getLockedBalance';
    address: string;
    zone: Zone;
} | {
    method: 'getOutpointsByAddress';
    address: string;
    zone: Zone;
} | {
    method: 'getBlock';
    blockTag: BlockTag;
    includeTransactions: boolean;
    shard: Shard;
} | {
    method: 'getBlock';
    blockHash: string;
    includeTransactions: boolean;
    shard: Shard;
} | {
    method: 'getBlockNumber';
    shard?: Shard;
} | {
    method: 'getCode';
    address: string;
    blockTag: BlockTag;
    zone: Zone;
} | {
    method: 'getGasPrice';
    txType: boolean;
    zone?: Zone;
} | {
    method: 'getLogs';
    filter: PerformActionFilter;
    zone: Zone;
} | {
    method: 'getStorage';
    address: string;
    position: bigint;
    blockTag: BlockTag;
    zone: Zone;
} | {
    method: 'getTransaction';
    hash: string;
    zone: Zone;
} | {
    method: 'getTransactionCount';
    address: string;
    blockTag: BlockTag;
    zone: Zone;
} | {
    method: 'getTransactionReceipt';
    hash: string;
    zone: Zone;
} | {
    method: 'getTransactionResult';
    hash: string;
    zone: Zone;
} | {
    method: 'getRunningLocations';
    shard?: Shard;
    now: boolean;
} | {
    method: 'getProtocolTrieExpansionCount';
    shard: Shard;
} | {
    method: 'qiToQuai';
    amt: string;
    blockTag: BlockTag;
    zone: Zone;
} | {
    method: 'quaiToQi';
    amt: string;
    blockTag: BlockTag;
    zone: Zone;
} | {
    method: 'getProtocolExpansionNumber';
} | {
    method: 'getPendingHeader';
} | {
    method: 'getTxPoolContent';
    zone: Zone;
} | {
    method: 'txPoolInspect';
    zone: Zone;
} | {
    method: 'getOutpointDeltasForAddressesInRange';
    addresses: string[];
    startHash: string;
    endHash: string;
    zone: Zone;
};

export interface ProtoTransaction {
    /**
     * The type of the transaction.
     */
    type: number;
    /**
     * The recipient address.
     */
    to?: Uint8Array | null;
    /**
     * The nonce of the transaction.
     */
    nonce?: number;
    /**
     * The value of the transaction.
     */
    value?: Uint8Array;
    /**
     * The gas limit for the transaction.
     */
    gas?: number;
    /**
     * The data of the transaction.
     */
    data?: Uint8Array;
    /**
     * The chain ID of the transaction.
     */
    chain_id: Uint8Array;
    /**
     * The gas price for the transaction.
     */
    gas_price?: Uint8Array;
    /**
     * The access list for the transaction.
     */
    access_list?: ProtoAccessList;
    /**
     * The V component of the signature.
     */
    v?: Uint8Array;
    /**
     * The R component of the signature.
     */
    r?: Uint8Array;
    /**
     * The S component of the signature.
     */
    s?: Uint8Array;
    /**
     * The originating transaction hash.
     */
    originating_tx_hash?: string;
    /**
     * The external transaction index.
     */
    etx_index?: number | null;
    /**
     * The external transaction sender.
     */
    etx_sender?: Uint8Array | null;
    work_nonce?: number | null;
    etx_type?: number | null;
    /**
     * The transaction inputs.
     */
    tx_ins?: {
        tx_ins: Array<ProtoTxInput>;
    };
    /**
     * The transaction outputs.
     */
    tx_outs?: {
        tx_outs: Array<ProtoTxOutput>;
    };
    /**
     * The signature of the transaction.
     */
    signature?: Uint8Array;
}

export interface QiAddressInfo extends NeuteredAddressInfo {
    change: boolean;
    status: AddressStatus;
    derivationPath: DerivationPath;
    lastSyncedBlock: LastSyncedBlock | null;
}

export interface quaisError<T extends ErrorCode = ErrorCode> extends Error {
    /**
     * The string error code.
     */
    code: ErrorCode;
    /**
     * A short message describing the error, with minimal additional details.
     */
    shortMessage: string;
    /**
     * Additional info regarding the error that may be useful.
     *
     * This is generally helpful mostly for human-based debugging.
     */
    info?: Record<string, any>;
    /**
     * Any related error.
     */
    error?: Error;
}

export interface ReplacementUnderpricedError extends quaisError<'REPLACEMENT_UNDERPRICED'> {
    /**
     * The transaction.
     */
    transaction: TransactionRequest;
}

export interface SerializedHDWallet {
    version: number;
    phrase: string;
    coinType: AllowedCoinType;
}

export interface SerializedQiHDWallet extends SerializedHDWallet {
    addresses: Array<QiAddressInfo>;
    senderPaymentCodeInfo: {
        [key: string]: QiAddressInfo[];
    };
}

export interface ServerError extends quaisError<'SERVER_ERROR'> {
    /**
     * The requested resource.
     */
    request: FetchRequest | string;
    /**
     * The response received from the server, if available.
     */
    response?: FetchResponse;
}

export type SignatureLike = Signature | string | {
    r: string;
    s: string;
    v: BigNumberish;
    yParity?: 0 | 1;
    yParityAndS?: string;
} | {
    r: string;
    yParityAndS: string;
    yParity?: 0 | 1;
    s?: string;
    v?: number;
} | {
    r: string;
    s: string;
    yParity: 0 | 1;
    v?: BigNumberish;
    yParityAndS?: string;
};

export interface Subscriber {
    /**
     * Called initially when a subscriber is added the first time.
     */
    start(): void;
    /**
     * Called when there are no more subscribers to the event.
